/**
 * Replay store — PostgreSQL persistence for the match event log.
 *
 * Schema (created idempotently on init):
 * - `matches`      — one row per played match: id (uuid, generated by the
 *                    game server), lobby code, start/end dates, result and
 *                    snapshots of settings + roster.
 * - `match_events` — the append-only event log: every recorded action as a
 *                    jsonb row, ordered by (match_id, seq). seq is assigned
 *                    by the recorder in arrival order, so a replay can be
 *                    re-driven deterministically from the rows alone.
 *
 * All methods throw on failure — error handling lives in the service layer,
 * which must never let a DB problem break the game.
 */
import pg from 'pg'

export function createPgStore(databaseUrl) {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 5 })
  // An idle-client error (e.g. the DB going away) must not crash the process.
  pool.on('error', (err) => console.error('[replay] pg pool error:', err.message))

  let initialized = null

  /**
   * Create the schema if needed. Retries in the background until the DB is
   * reachable (docker-compose `depends_on: service_healthy` usually beats us
   * to it; this covers plain `node src/index.js` boots against a slow DB).
   */
  function init() {
    if (!initialized) {
      initialized = (async () => {
        for (;;) {
          try {
            await pool.query(`
              CREATE TABLE IF NOT EXISTS matches (
                id          UUID PRIMARY KEY,
                lobby_code  TEXT NOT NULL,
                started_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
                ended_at    TIMESTAMPTZ,
                winner      TEXT,
                reason      TEXT,
                settings    JSONB NOT NULL DEFAULT '{}'::jsonb,
                players     JSONB NOT NULL DEFAULT '[]'::jsonb,
                event_count INTEGER NOT NULL DEFAULT 0
              );
              CREATE TABLE IF NOT EXISTS match_events (
                match_id UUID    NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
                seq      INTEGER NOT NULL,
                at       TIMESTAMPTZ NOT NULL,
                event    TEXT    NOT NULL,
                payload  JSONB   NOT NULL,
                PRIMARY KEY (match_id, seq)
              );
            `)
            return
          } catch (err) {
            console.error('[replay] schema init failed, retrying in 5 s:', err.message)
            await new Promise((r) => setTimeout(r, 5000))
          }
        }
      })()
    }
    return initialized
  }

  async function insertMatch(match) {
    // { id, lobbyCode, startedAt, settings, players }
    await pool.query(
      `INSERT INTO matches (id, lobby_code, started_at, settings, players)
       VALUES ($1, $2, $3, $4, $5)`,
      [match.id, match.lobbyCode, match.startedAt, JSON.stringify(match.settings ?? {}), JSON.stringify(match.players ?? [])],
    )
  }

  /** Append a batch of events: [{ seq, at, event, payload }] in seq order. */
  async function insertEvents(matchId, rows) {
    if (!rows.length) return
    // Multi-row insert in chunks that stay far below the 65535-param limit
    // (4 params per row → 500 rows = 2000 params).
    for (let i = 0; i < rows.length; i += 500) {
      const chunk = rows.slice(i, i + 500)
      const values = []
      const params = []
      chunk.forEach((row, j) => {
        const b = j * 4
        values.push(`($1, $${b + 2}, $${b + 3}, $${b + 4}, $${b + 5})`)
        params.push(row.seq, row.at, row.event, JSON.stringify(row.payload ?? {}))
      })
      await pool.query(
        `INSERT INTO match_events (match_id, seq, at, event, payload)
         VALUES ${values.join(',')}`,
        [matchId, ...params],
      )
    }
  }

  async function finishMatch(matchId, { endedAt, winner, reason, eventCount }) {
    await pool.query(
      `UPDATE matches
       SET ended_at = $2, winner = $3, reason = $4, event_count = $5
       WHERE id = $1`,
      [matchId, endedAt, winner, reason, eventCount],
    )
  }

  async function listMatches({ limit = 100 } = {}) {
    const { rows } = await pool.query(
      `SELECT id, lobby_code AS "lobbyCode", started_at AS "startedAt", ended_at AS "endedAt",
              winner, reason, event_count AS "eventCount",
              jsonb_array_length(players) AS "playerCount"
       FROM matches
       ORDER BY started_at DESC
       LIMIT $1`,
      [limit],
    )
    return rows
  }

  async function getMatch(id) {
    const { rows } = await pool.query(
      `SELECT id, lobby_code AS "lobbyCode", started_at AS "startedAt", ended_at AS "endedAt",
              winner, reason, settings, players, event_count AS "eventCount"
       FROM matches
       WHERE id = $1`,
      [id],
    )
    return rows[0] ?? null
  }

  async function getEvents(id) {
    const { rows } = await pool.query(
      `SELECT seq, at, event, payload
       FROM match_events
       WHERE match_id = $1
       ORDER BY seq`,
      [id],
    )
    return rows
  }

  return { init, insertMatch, insertEvents, finishMatch, listMatches, getMatch, getEvents }
}
